       private Map<String, Set<String>> mLayoutIncludes;
       private Set<Location> mReported;

       @Override
       public void beforeCheckProject(Context context) {
           mLayoutIds = new HashMap<>();
           mLayoutIncludes = new HashMap<>();
           mReported = new HashSet<>();
       }

       @Override
       public void afterCheckProject(Context context) {
           if (mLayoutIds.isEmpty()) {
               return;
           }

           for (String rootLayout : mLayoutIds.keySet()) {
               Map<String, Location> seenIds = new HashMap<>();
               Set<String> visitedLayouts = new HashSet<>();
               Deque<String> stack = new ArrayDeque<>();
               stack.push(rootLayout);

               while (!stack.isEmpty()) {
                   String current = stack.pop();
                   if (!visitedLayouts.add(current)) {
                       continue;
                   }

                   Map<String, Location> ids = mLayoutIds.get(current);
                   if (ids != null) {
                       for (Map.Entry<String, Location> entry : ids.entrySet()) {
                           String id = entry.getKey();
                           Location loc = entry.getValue();
                           Location existing = seenIds.get(id);
                           if (existing != null) {
