                   if (includes != null) {
                       for (String inc : includes) {
                           stack.push(inc);
                       }
                   }
               }
           }

           mLayoutIds = null;
           mLayoutIncludes = null;
           mReported = null;
       }

       @Override
       public Collection<String> getApplicableElements() {
           return null; // Visit all elements
       }

