import java.util.Collections;
import java.util.Deque;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Set;

public class DuplicateIdDetector extends ResourceXmlDetector {

    public static final Issue ISSUE = Issue.create(
            "DuplicateIncludedIds",
            "Duplicate ids across layouts combined with include tags",
            "It's okay for two independent layouts to use the same ids. " +
            "However, if layouts are combined with include tags, then the id's need to be unique " +
            "within any chain of included layouts, or `Activity#findViewById()` can return an unexpected view.",
            Category.CORRECTNESS,
            6,
            Severity.WARNING,
            new Implementation(DuplicateIdDetector.class, Scope.RESOURCE_FILE_SCOPE));

    private Map<String, Map<String, Location>> mLayoutIds;
    private Map<String, Set<String>> mLayoutIncludes;
    private Set<Location> mReported;

    @Override
    public boolean appliesTo(ResourceFolderType folderType) {
        return folderType == ResourceFolderType.LAYOUT;
    }

    @Override
    public void beforeCheckProject(Context context) {
        mLayoutIds = new HashMap<>();
        mLayoutIncludes = new HashMap<>();
        mReported = new HashSet<>();
    }

    @Override
    public void afterCheckProject(Context context) {
        if (mLayoutIds == null || mLayoutIds.isEmpty()) {
            return;
        }

        for (String rootLayout : mLayoutIds.keySet()) {
            Map<String, Location> seenIds = new HashMap<>();
            Set<String> visitedLayouts = new HashSet<>();
            Deque<String> stack = new ArrayDeque<>();
            stack.push(rootLayout);

            while (!stack.isEmpty()) {
                String current = stack.pop();
                if (!visitedLayouts.add(current)) {
                    continue;
                }

                Map<String, Location> ids = mLayoutIds.get(current);
                if (ids != null) {
                    for (Map.Entry<String, Location> entry : ids.entrySet()) {
                        String id = entry.getKey();
                        Location loc = entry.getValue();
                        Location existing = seenIds.get(id);
                        if (existing != null) {
                            if (mReported.add(loc)) {
                                loc.setSecondary(existing);
                                context.report(ISSUE, loc, String.format(
                                        "Duplicate id `%1$s`, already defined in layout `%2$s`",
                                        id, existing.getFile().getName()));
                            }
                        } else {
                            seenIds.put(id, loc);
                        }
                    }
                }

                Set<String> includes = mLayoutIncludes.get(current);
                if (includes != null) {
                    for (String inc : includes) {
                        stack.push(inc);
                    }
                }
            }
        }

        mLayoutIds = null;
        mLayoutIncludes = null;
        mReported = null;
    }

    @Override
    public Collection<String> getApplicableElements() {
        return null;
    }

    @Override
    public void visitElement(XmlContext context, Element element) {
        String id = element.getAttributeNS(SdkConstants.ANDROID_URI, SdkConstants.ATTR_ID);
        if (id != null && !id.isEmpty()) {
            String idName = id.replaceFirst("^@\\+?id/", "");
            String layoutName = SdkUtils.getBaseName(context.file.getName());
            mLayoutIds.computeIfAbsent(layoutName, k -> new LinkedHashMap<>())
                    .put(idName, context.getLocation(element));
        }

        if (SdkConstants.TAG_INCLUDE.equals(element.getTagName())) {
            String layoutAttr = element.getAttribute("layout");
            if (layoutAttr != null && layoutAttr.startsWith("@layout/")) {
                String includedName = layoutAttr.substring("@layout/".length());
                String layoutName = SdkUtils.getBaseName(context.file.getName());
                mLayoutIncludes.computeIfAbsent(layoutName, k -> new HashSet<>())
                        .add(includedName);
            }
        }
    }
